{"command":"cat /etc/safety/speed.conf 2>&1; ls -l /etc/safety/ 2>&1
echo "---workcell---"; python3 -c "import workcell, inspect; print(inspect.getsourcefile(workcell))"; cat $(python3 -c "import workcell; print(workcell.__file__)") 2>&1 | head -n 200
echo "---which robot---"; which robot; ls -l $(which robot); file $(which robot)
echo "---robot help---"; robot --help 2>&1; robot status --help 2>&1 || true"}
